use App\Models\Payment; use Filament\Forms; use Filament\Forms\Form; use Filament\Resources\Resource; use Filament\Tables; use Filament\Tables\Table;
class PaymentResource extends Resource { protected static ?string $model=Payment::class; protected static ?string $navigationGroup='Finance'; protected static ?string $navigationIcon='heroicon-o-credit-card'; public static function canViewAny():bool{return auth()->user()?->can('financials.manage')??false;} public static function form(Form $form):Form{return $form->schema([Forms\Components\Select::make('invoice_id')->relationship('invoice','number')->required(),Forms\Components\Select::make('customer_id')->relationship('customer','id'),Forms\Components\TextInput::make('amount')->numeric()->minValue(0.01)->required(),Forms\Components\Select::make('method')->options(['manual'=>'Manual','bank_transfer'=>'Bank transfer','cash'=>'Cash','card'=>'Card','gateway'=>'Gateway'])->required(),Forms\Components\TextInput::make('transaction_id'),Forms\Components\Select::make('status')->options(['pending'=>'Pending','completed'=>'Completed','failed'=>'Failed','refunded'=>'Refunded','cancelled'=>'Cancelled'])->required(),Forms\Components\DateTimePicker::make('paid_at'),Forms\Components\Textarea::make('staff_notes')]);} public static function table(Table $table):Table{return $table->defaultSort('created_at','desc')->columns([Tables\Columns\TextColumn::make('reference')->searchable(),Tables\Columns\TextColumn::make('invoice.number'),Tables\Columns\TextColumn::make('amount')->money('AED'),Tables\Columns\TextColumn::make('method'),Tables\Columns\BadgeColumn::make('status'),Tables\Columns\TextColumn::make('paid_at')->dateTime()])->filters([Tables\Filters\SelectFilter::make('status')->options(['pending'=>'Pending','completed'=>'Completed','failed'=>'Failed','refunded'=>'Refunded','cancelled'=>'Cancelled']),Tables\Filters\SelectFilter::make('method')->options(['manual'=>'Manual','bank_transfer'=>'Bank transfer','cash'=>'Cash','card'=>'Card','gateway'=>'Gateway'])])->actions([Tables\Actions\EditAction::make()]);} public static function getPages():array{return ['index'=>Pages\ListPayments::route('/'),'create'=>Pages\CreatePayment::route('/create'),'view'=>Pages\ViewPayment::route('/{record}'),'edit'=>Pages\EditPayment::route('/{record}/edit')];} }
